        return this;
    };
    this.value = () => {
        res = void(0);
        for (k in this.keyPairs) {
            kv = `${k}=${this.keyPairs[k]};`;
            res = res === void(0) ?
                kv :
                res + kv;
        }
        return res;
    };
}
