@js:
function login() {
    var info = source.getLoginInfoMap() || {};
    var u = info.get ? info.get('账号') : info['账号'];
    var p = info.get ? info.get('密码') : info['密码'];
    if (!u || !p) throw new Error('请先填写账号和密码');
    var r = JSON.parse(java.ajax(lkUrl('/bff/auth-password-login-v1', {username: String(u), password: String(p)})));
    if (r.code == 0 && r.data && r.data.auth && r.data.auth.security_key) {
        source.put('lk_key', String(r.data.auth.security_key));
        java.toast('✅ 登录成功：' + ((r.data.user && r.data.user.nickname) || r.data.auth.uid));
        return;
    }
    throw new Error(r.code == 2 ? '账号或密码错误' : '登录失败 code:' + r.code);
}

function lkStatus() {
    var key = lkKey(source);
    if (!key) { java.toast('⚪ 未登录'); return; }
    var r = JSON.parse(java.ajax(lkUrl('/bff/auth-session-v1', {}, key)));
    if (r.code == 0 && r.data && r.data.logged_in == 1) {
        var u = r.data.user || {};
        java.toast('✅ 已登录：' + (u.nickname || u.uid) + (u.level ? '（' + u.level.name + '）' : ''));
    } else {
        java.toast('⚠️ 登录已失效，请重新登录');
    }
}

function lkLogout() {
    source.put('lk_key', '');
    java.toast('🚪 已退出登录');
}

function lkToggleCoin() {
    var on = !lkCoinOn(source);
    source.put('lk_coin', on ? '1' : '');
    java.toast(on ? '💰 花费轻币：已开启（打开付费章节时自动解锁）' : '💰 花费轻币：已关闭');
}

function lkToggleZh() {
    var on = !lkZhOn(source);
    source.put('lk_zh', on ? '1' : '');
    java.toast(on ? '🈶 繁转简：已开启（刷新目录后生效）' : '🈶 繁转简：已关闭');
}

ruleContent.content:
@js:
var d = JSON.parse(result).data || {};
var key = lkKey(source);
var coinOn = lkCoinOn(source);
var err = '';
function reload() {
    try { d = JSON.parse(java.ajax(lkChapter(d.chapter_id, key))).data || d; } catch (e) {}
}
if (d.locked == 1 && key) {
    reload();
    if (d.locked == 1 && d.access_type == 'coin' && coinOn) {
        try {
            var u = JSON.parse(java.ajax(lkUrl('/new-content-read/unlock-chapter', {chapter_id: d.chapter_id}, key, true)));
            if (u.code == 0) reload();
            else err = String((u.data && u.data.message) || u.message || 'code ' + u.code);
        } catch (e) { err = String(e); }
    }
}
var out = lkHtml(d);
if (d.locked == 1) out = (out ? out + '\n' : '') + lkLockTip(d, !!key, coinOn, err);
else if (!out) out = '⚠️ 本章暂无内容';
if (lkZhOn(source)) out = String(java.t2s(out));
out;

ruleToc.chapterList:
@js:
var key = lkKey(source);
var zh = lkZhOn(source);
var d = JSON.parse(result).data || {};
var vols = d.volumes || [];
if (vols.length < (d.volume_count || 0)) {
    vols = [];
    for (var p = 1, pages = 1; p <= pages; p++) {
        var r = JSON.parse(java.ajax(lkUrl('/new-content-read/get-book-volumes', {book_id: d.book_id, page: p, page_size: 50}, key))).data || {};
        pages = (r.pagination && r.pagination.page_count) || 1;
        vols = vols.concat(r.list || []);
    }
}

var BATCH = 4;
var pages = {};
var queue = vols.map(function (v, i) { return [i, 1]; });
while (queue.length) {
    var batch = queue.splice(0, BATCH);
    var res = java.ajaxAll(batch.map(function (t) {
        return lkUrl('/new-content-read/get-volume-chapters', {volume_id: vols[t[0]].volume_id, page: t[1], page_size: 50}, key);
    }));
    batch.forEach(function (t, j) {
        var body = String(res[j].body());
        var r;
        try { r = JSON.parse(body).data || {}; } catch (e) { throw new Error('目录获取失败：' + body.slice(0, 60)); }
        pages[t[0] + ':' + t[1]] = r.list || [];
        var count = (r.pagination && r.pagination.page_count) || 1;
        if (t[1] == 1) for (var n = 2; n <= count; n++) queue.push([t[0], n]);
    });
}

var out = [];
vols.forEach(function (v, i) {
    var vt = String(v.title || '');
    out.push(JSON.stringify({title: zh ? String(java.t2s(vt)) : vt, url: '', volume: 'true', vip: '', time: ''}));
    for (var n = 1; pages[i + ':' + n]; n++) {
        pages[i + ':' + n].forEach(function (c) {
            var t = String(c.title || '');
            if (zh) t = String(java.t2s(t));
            var lock = c.locked == 1;
            out.push(JSON.stringify({
                title: (lock ? '🔒 ' : '') + t,
                url: lkChapter(c.chapter_id),
                volume: '',
                vip: lock ? 'true' : '',
                time: String(c.published_at || '')
            }));
        });
    }
});
out;

